+    assert.throws(() => buildPayloads({ ...f.input, earlierLiquid: [{
+      ...row, original: { ...row.original, source: a(99) },
+    }] }), { code: "DOMAIN" });
+    assert.throws(() => buildPayloads({ ...f.input, earlierLiquid: [{
+      ...row, original: { ...row.original, originalUnits: "10000" },
+    }] }), { code: "PROVENANCE" });
